import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CegG7-6m.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788874080000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>CALDAV_READ_ONLY</code> is set, and it is a write tool.</li><li><code>CALDAV_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out.</li><li><code>CALDAV_DENY_TOOLS</code> names it, possibly through a prefix such as <code>delete_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot; — the same as a write tool under read-only. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><h2 id="the-listing-is-empty-and-the-calendar-is-not" tabindex="-1">The listing is empty and the calendar is not <a class="header-anchor" href="#the-listing-is-empty-and-the-calendar-is-not" aria-label="Permalink to “The listing is empty and the calendar is not”">​</a></h2><p>An empty answer where the server clearly holds entries is usually the reader and the server disagreeing about how the iCalendar document was packed into the response, not a filter or a permission.</p><p><code>calendar-data</code> is read as <strong>raw source</strong> — deliberately, so that a description containing a <code>&lt;</code> stays a description rather than becoming markup — which means the XML packaging arrives with it and has to be taken off. Versions before 0.1.4 did not take off a <code>&lt;![CDATA[…]]&gt;</code> section or leading indentation, so the document handed to the parser began <code>&lt;![CDATA[BEGIN:</code> or <code>\\n BEGIN:</code> and no parser accepts either. carddav-mcp met exactly that against Open-Xchange, where an address book of 79 cards listed as empty.</p><p>If you see this on 0.1.4 or later, the packaging is one nobody has met yet — an XML comment inside the node would do it. Please open an issue with the raw <code>REPORT</code> response; that is the one thing the fix cannot be guessed from.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};